CREATE POLICY "vault photos public read" ON storage.objects FOR SELECT USING (bucket_id = 'vault-photos');
CREATE POLICY "vault photos admin insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'vault-photos' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "vault photos admin update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'vault-photos' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "vault photos admin delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'vault-photos' AND public.has_role(auth.uid(),'admin'));